        assert_eq!(
            recommended_speech_model_id(mac14, None, false),
            "parakeet-tdt-v3"
        );
        assert_eq!(
            recommended_speech_model_id(mac14, Some("de"), false),
            "parakeet-tdt-v3"
        );
        assert_eq!(
            recommended_speech_model_id(
