                    let matches = CATALOG
                        .iter()
                        .filter(|m| m.offered_on(*platform, fluid) && m.id == id)
                        .count();
                    assert_eq!(
                        matches, 1,
                        "{platform:?}/{language:?}/bridge={fluid} -> {id}"
                    );
                }
            }
        }
    }

