        for id in ["apple-speech-transcriber", "apple-dictation-transcriber"] {
            let row = find(id).unwrap_or_else(|| panic!("{id} missing from CATALOG"));
            assert_eq!(row.engine, Engine::AppleSpeech, "{id}");
