    #[test]
    fn load_cell_falls_back_to_report_model_without_meta() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("report.json"), REPORT).unwrap();
        let c = load_cell(dir.path().to_str().unwrap(), None, None).unwrap();
