        assert_eq!(
            recommended_speech_model_id(Platform::Windows, Some("pt-BR"), false),
            "sherpa-parakeet-v3-int8"
        );
        assert_eq!(
            recommended_speech_model_id(mac14, Some("ja-JP"), true),
